function pickFinalAlgoCandidate(pool,selected){
  const formatCounts={};
  selected.forEach(x=>formatCounts[x.format||'トレース']=(formatCounts[x.format||'トレース']||0)+1);
  return [...pool].sort((a,b)=>{
    const sa=bFinalAlgoSeen(a),sb=bFinalAlgoSeen(b);
    if(sa!==sb)return sa-sb;
    const fa=formatCounts[a.format||'トレース']||0,fb=formatCounts[b.format||'トレース']||0;
    if(fa!==fb)return fa-fb;
    return Math.random()-.5;
  })[0]||null;
}

